    });
    const setup = resolveGameSetup(runtime, {
      recordRootDir: root,
      maxDays: 30,
      streamEvents: false,
      color: false,
    });
    let closed = 0;
    const create = spyOn(factory, "createPlayerAgentRuntime").mockImplementation(
      async (options) => ({
        kind: "llm",
        runtimeState: { closed: false },
